steps.command:
python3 -c "import json,time,urllib.request; cases=json.load(open('eval-cases.json'))['cases']; sys_p='You classify support tickets. Reply with ONLY a JSON object with fields: reasoning (string), urgency (low|medium|high|critical), category (billing|bug|feature_request|account|other), suggested_action (auto_reply|route_to_billing|escalate|human_review), confidence (0.0 to 1.0).';
import pathlib; out=[]
for c in cases:
    p={'model':'qwen3.5:2b','stream':False,'think':False,'format':'json','options':{'temperature':0},'messages':[{'role':'system','content':sys_p},{'role':'user','content':c['input']}]}
    r=urllib.request.Request('http://127.0.0.1:11434/api/chat',method='POST',data=json.dumps(p).encode(),headers={'Content-Type':'application/json'})
    t=time.monotonic(); b=json.load(urllib.request.urlopen(r,timeout=120)); out.append({'case_id':c['case_id'],'seconds':round(time.monotonic()-t,2),'raw':b['message']['content']})
pathlib.Path('local-route-run.json').write_text(json.dumps(out,indent=2)); print('saved', len(out), 'responses')"
